    "integrators.scenarios_title": "Escenarios de integración",
    "integrators.scenarios_subtitle": "IAES se mapea a cinco patrones comunes de integración industrial.",
    "integrators.scenario1_title": "Gateway de sensores",
    "integrators.scenario1_desc": "Normaliza telemetría cruda de cualquier sensor en eventos estructurados.",
    "integrators.scenario2_title": "Motor AI / ML",
