    "cmp.row_bestfor": "Ideal pour",
    "cmp.opcua_bestfor": "M2M en usine, SCADA",
    "cmp.spb_bestfor": "Telemetrie edge-vers-cloud",
    "cmp.aas_bestfor": "Registres de jumeaux numeriques",
    "cmp.iaes_bestfor": "Interoperabilite evenementielle inter-systemes",
    "cmp.row_adoption": "Adoption",
    "cmp.opcua_adoption": "Repandue (etablie)",
    "cmp.spb_adoption": "En croissance (IIoT)",
