    "integrators.scenarios_title": "Scenari di integrazione",
    "integrators.scenarios_subtitle": "IAES corrisponde a cinque pattern comuni di integrazione industriale.",
    "integrators.scenario1_title": "Gateway sensori",
    "integrators.scenario1_desc": "Normalizza la telemetria grezza da qualsiasi sensore in eventi strutturati.",
    "integrators.scenario2_title": "Motore AI / ML",
