    // Integration Pipeline
    "integration.title": "\uc13c\uc11c\uc5d0\uc11c \uc561\uc158\uc73c\ub85c",
    "integration.subtitle": "\uc13c\uc11c\uac00 \ubca0\uc5b4\ub9c1 \ub9c8\ubaa8\ub97c \uac10\uc9c0\ud569\ub2c8\ub2e4. AI \ubaa8\ub378\uc774 \uacb0\ud568\uc744 \ubd84\ub958\ud558\uac70\ub098 \uae30\uc220\uc790\uac00 \ubaa8\ubc14\uc77c \uc571\uc5d0\uc11c \uc9c4\ub2e8\uc744 \uae30\ub85d\ud569\ub2c8\ub2e4. \uc5b4\ub290 \ucabd\uc774\ub4e0 IAES\ub294 \ud558\ub098\uc758 \uc774\ubca4\ud2b8\ub97c \uc138 \uc2dc\uc2a4\ud15c\uc5d0 \ub3d9\uc2dc\uc5d0 \ub77c\uc6b0\ud305\ud569\ub2c8\ub2e4.",
    "integration.sensor": "\uc9c4\ub3d9 \uc13c\uc11c",
    "integration.intelligence": "AI / \uc804\ubb38\uac00 / \uc571",
    "integration.sap": "IW31 \uc54c\ub9bc",
    "integration.maintainx": "\uc791\uc5c5 \uc9c0\uc2dc\uc11c \ud560\ub2f9\ub428",
    "integration.grafana": "\uc54c\ub9bc \ud328\ub110 \ubc1c\uc0dd",
    "integration.note": "\ud558\ub098\uc758 \uc774\ubca4\ud2b8, \uc138 \uc18c\ube44\uc790. \ub300\uc0c1 \uc2dc\uc2a4\ud15c\ubcc4 \ub9de\ucda4 \ud1b5\ud569 \uc5c6\uc74c. \uc9c0\ub2a5\uc774 \uc778\uacf5\uc774\ub4e0 \uc778\uac04\uc774\ub4e0 \u2014 \uc774\ubca4\ud2b8 \ud615\uc2dd\uc740 \ub3d9\uc77c\ud569\ub2c8\ub2e4.",
    // Incident Lifecycle
    "incident.title": "\uc778\uc2dc\ub358\ud2b8 \uc218\uba85 \uc8fc\uae30",
    "incident.subtitle": "\uac10\uc9c0\ubd80\ud130 \ud574\uacb0\uae4c\uc9c0 \uc644\uc804\ud55c \uc778\uc2dc\ub358\ud2b8. \ub124 \uac1c\uc758 IAES \uc774\ubca4\ud2b8\uac00 \uc804\uccb4 \uc2a4\ud1a0\ub9ac\ub97c \uc804\ud569\ub2c8\ub2e4 \u2014 \uc54c\ub9bc\uc744 \ub2eb\uae30 \uc704\ud55c \uc778\uac04 \uac1c\uc785\uc774 \ud544\uc694 \uc5c6\uc2b5\ub2c8\ub2e4.",
    "incident.onset_desc": "\uc5ed\ub960\uc774 0.91\ub85c \ud558\ub77d\ud569\ub2c8\ub2e4. \uaddc\uce59 \uc5d4\uc9c4\uc774 \uc704\ubc18\uc744 \uac10\uc9c0\ud569\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 correlation_id\uac00 \uc0dd\uc131\ub429\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \uc54c\ub9bc\uc774 \uc0dd\uc131\ub429\ub2c8\ub2e4.",
    "incident.escalation_desc": "\uc5ed\ub960\uc774 0.84\ub85c \ucd94\uac00 \ud558\ub77d\ud569\ub2c8\ub2e4. \uc2ec\uac01\ub3c4\uac00 \uc911\uac04\uc5d0\uc11c \ub192\uc74c\uc73c\ub85c \uc5d0\uc2a4\uceec\ub808\uc774\uc158\ub429\ub2c8\ub2e4. \ub3d9\uc77c\ud55c correlation_id. \uc911\ubcf5 \uc54c\ub9bc \uc5c6\uc74c \u2014 \uae30\uc874 \uc54c\ub9bc\uc774 \uc5c5\ub370\uc774\ud2b8\ub429\ub2c8\ub2e4.",
    "incident.wo_desc": "\uc18c\ube44\uc790\uac00 MaintainX\uc5d0\uc11c \uc791\uc5c5 \uc9c0\uc2dc\uc11c\ub97c \uc0dd\uc131\ud569\ub2c8\ub2e4. \ub3d9\uc77c\ud55c correlation_id\uc5d0 \uc5f0\uacb0\ub429\ub2c8\ub2e4. \ucee4\ud328\uc2dc\ud130 \ubc45\ud06c \uc810\uac80\uc744 \uc704\ud574 \uae30\uc220\uc790\uac00 \ud30c\uacac\ub429\ub2c8\ub2e4.",
    "incident.recovery_desc": "\uc5ed\ub960\uc774 5\ud68c \uc5f0\uc18d \uce21\uc815\uc5d0\uc11c 0.97\ub85c \ud68c\ubcf5\ub429\ub2c8\ub2e4. severity: info, condition_trend: improving\uc73c\ub85c \ubcf5\uad6c \uc774\ubca4\ud2b8\uac00 \ubc1c\uc0dd\ud569\ub2c8\ub2e4. \uc54c\ub9bc\uc774 \uc790\ub3d9 \ud574\uacb0\ub429\ub2c8\ub2e4.",
    "incident.correlation": "correlation_id: 3b2f9d8c-1c33-4a8a \u2014 4\uac1c \uc774\ubca4\ud2b8 \ubaa8\ub450 \ub3d9\uc77c\ud55c ID\ub97c \uacf5\uc720\ud569\ub2c8\ub2e4. \ud558\ub098\uc758 \uc778\uc2dc\ub358\ud2b8, \ud558\ub098\uc758 \uc2a4\ub808\ub4dc, \uc644\uc804\ud55c \ucd94\uc801\uc131.",
