    // Integration Pipeline
    "integration.title": "\u041e\u0442 \u0434\u0430\u0442\u0447\u0438\u043a\u0430 \u043a \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044e",
    "integration.subtitle": "\u0414\u0430\u0442\u0447\u0438\u043a \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0438\u0432\u0430\u0435\u0442 \u0438\u0437\u043d\u043e\u0441 \u043f\u043e\u0434\u0448\u0438\u043f\u043d\u0438\u043a\u0430. \u041c\u043e\u0434\u0435\u043b\u044c AI \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u0442 \u043d\u0435\u0438\u0441\u043f\u0440\u0430\u0432\u043d\u043e\u0441\u0442\u044c \u2014 \u0438\u043b\u0438 \u0442\u0435\u0445\u043d\u0438\u043a \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442 \u0434\u0438\u0430\u0433\u043d\u043e\u0437 \u0447\u0435\u0440\u0435\u0437 \u043c\u043e\u0431\u0438\u043b\u044c\u043d\u043e\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435. \u0412 \u043b\u044e\u0431\u043e\u043c \u0441\u043b\u0443\u0447\u0430\u0435 IAES \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u043e\u0434\u043d\u043e \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u0432 \u0442\u0440\u0438 \u0441\u0438\u0441\u0442\u0435\u043c\u044b \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e.",
    "integration.sensor": "\u0414\u0430\u0442\u0447\u0438\u043a \u0432\u0438\u0431\u0440\u0430\u0446\u0438\u0438",
    "integration.intelligence": "AI / \u042d\u043a\u0441\u043f\u0435\u0440\u0442 / \u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435",
    "integration.sap": "\u0423\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u0435 IW31",
    "integration.maintainx": "\u041d\u0430\u0440\u044f\u0434 \u043d\u0430 \u0440\u0430\u0431\u043e\u0442\u0443 \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d",
    "integration.grafana": "\u041f\u0430\u043d\u0435\u043b\u044c \u043e\u043f\u043e\u0432\u0435\u0449\u0435\u043d\u0438\u044f \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u043b\u0430",
    "integration.note": "\u041e\u0434\u043d\u043e \u0441\u043e\u0431\u044b\u0442\u0438\u0435, \u0442\u0440\u0438 \u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u044f. \u041d\u0438\u043a\u0430\u043a\u043e\u0439 \u0438\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u043e\u0439 \u0438\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438 \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u044b. \u0418\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0438\u043b\u0438 \u0447\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u043a\u0438\u0439 \u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442 \u2014 \u0444\u043e\u0440\u043c\u0430\u0442 \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432.",
    // Incident Lifecycle
    "incident.title": "\u0416\u0438\u0437\u043d\u0435\u043d\u043d\u044b\u0439 \u0446\u0438\u043a\u043b \u0438\u043d\u0446\u0438\u0434\u0435\u043d\u0442\u0430",
    "incident.subtitle": "\u041f\u043e\u043b\u043d\u044b\u0439 \u0438\u043d\u0446\u0438\u0434\u0435\u043d\u0442 \u043e\u0442 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u0434\u043e \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f. \u0427\u0435\u0442\u044b\u0440\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u044f IAES \u0440\u0430\u0441\u0441\u043a\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u043f\u043e\u043b\u043d\u0443\u044e \u0438\u0441\u0442\u043e\u0440\u0438\u044e \u2014 \u043d\u0438\u043a\u0430\u043a\u043e\u0433\u043e \u0432\u043c\u0435\u0448\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430 \u0434\u043b\u044f \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u044f \u043e\u043f\u043e\u0432\u0435\u0449\u0435\u043d\u0438\u044f.",
    "incident.onset_desc": "\u041a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u043f\u0430\u0434\u0430\u0435\u0442 \u0434\u043e 0.91. \u041c\u043e\u0442\u043e\u0440 \u043f\u0440\u0430\u0432\u0438\u043b \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0438\u0432\u0430\u0435\u0442 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0435. \u0413\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043d\u043e\u0432\u044b\u0439 correlation_id. \u041f\u0435\u0440\u0432\u043e\u0435 \u043e\u043f\u043e\u0432\u0435\u0449\u0435\u043d\u0438\u0435 \u0441\u043e\u0437\u0434\u0430\u043d\u043e.",
    "incident.escalation_desc": "\u041a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u043f\u0430\u0434\u0430\u0435\u0442 \u0434\u043e 0.84. \u0421\u0435\u0440\u044c\u0451\u0437\u043d\u043e\u0441\u0442\u044c \u044d\u0441\u043a\u0430\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u0441\u043e \u0441\u0440\u0435\u0434\u043d\u0435\u0439 \u0434\u043e \u0432\u044b\u0441\u043e\u043a\u043e\u0439. \u0422\u043e\u0442 \u0436\u0435 correlation_id. \u0411\u0435\u0437 \u0434\u0443\u0431\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u043e\u043f\u043e\u0432\u0435\u0449\u0435\u043d\u0438\u0439 \u2014 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0435 \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u043e.",
    "incident.wo_desc": "\u041f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u044c \u0441\u043e\u0437\u0434\u0430\u0451\u0442 \u043d\u0430\u0440\u044f\u0434 \u043d\u0430 \u0440\u0430\u0431\u043e\u0442\u0443 \u0432 MaintainX. \u041f\u0440\u0438\u0432\u044f\u0437\u0430\u043d \u043a \u0442\u043e\u043c\u0443 \u0436\u0435 correlation_id. \u0422\u0435\u0445\u043d\u0438\u043a \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d \u0434\u043b\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u043a\u043e\u043d\u0434\u0435\u043d\u0441\u0430\u0442\u043e\u0440\u043d\u043e\u0439 \u0431\u0430\u0442\u0430\u0440\u0435\u0438.",
    "incident.recovery_desc": "\u041a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0434\u043e 0.97 \u043d\u0430 5 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f\u0445. \u0421\u043e\u0431\u044b\u0442\u0438\u0435 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u0441 severity: info, condition_trend: improving. \u041e\u043f\u043e\u0432\u0435\u0449\u0435\u043d\u0438\u0435 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u0430\u043a\u0440\u044b\u0442\u043e.",
    "incident.correlation": "correlation_id: 3b2f9d8c-1c33-4a8a \u2014 \u0432\u0441\u0435 4 \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u0438\u043c\u0435\u044e\u0442 \u043e\u0434\u0438\u043d ID. \u041e\u0434\u0438\u043d \u0438\u043d\u0446\u0438\u0434\u0435\u043d\u0442, \u043e\u0434\u043d\u0430 \u0446\u0435\u043f\u043e\u0447\u043a\u0430, \u043f\u043e\u043b\u043d\u0430\u044f \u043f\u0440\u043e\u0441\u043b\u0435\u0436\u0438\u0432\u0430\u0435\u043c\u043e\u0441\u0442\u044c.",
    // Quickstart
    // Spec page
    "nav_spec": "\u0421\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f",
    "nav_examples": "Примеры",
    "nav_schemas": "Схемы",
    "nav_install": "Установка",
    "toc_title": "Содержание",
    "toc_purpose": "1. Назначение",
    "toc_principles": "2. Принципы",
    "toc_terminology": "3. Терминология",
