    "integration.title": "\u0645\u0646 \u0627\u0644\u0645\u0633\u062a\u0634\u0639\u0631 \u0625\u0644\u0649 \u0627\u0644\u0625\u062c\u0631\u0627\u0621",
    "integration.subtitle": "\u064a\u0643\u062a\u0634\u0641 \u0645\u0633\u062a\u0634\u0639\u0631 \u062a\u0622\u0643\u0644 \u0627\u0644\u0645\u062d\u0627\u0645\u0644. \u064a\u0635\u0646\u0651\u0641 \u0646\u0645\u0648\u0630\u062c \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0627\u0644\u0639\u0637\u0644 \u2014 \u0623\u0648 \u064a\u0633\u062c\u0651\u0644 \u0641\u0646\u064a \u062a\u0634\u062e\u064a\u0635\u064b\u0627 \u0645\u0646 \u062a\u0637\u0628\u064a\u0642 \u0645\u062d\u0645\u0648\u0644. \u0641\u064a \u0643\u0644\u062a\u0627 \u0627\u0644\u062d\u0627\u0644\u062a\u064a\u0646\u060c \u064a\u0648\u062c\u0651\u0647 IAES \u062d\u062f\u062b\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u0625\u0644\u0649 \u062b\u0644\u0627\u062b\u0629 \u0623\u0646\u0638\u0645\u0629 \u0641\u064a \u0622\u0646 \u0648\u0627\u062d\u062f.",
    "integration.sensor": "\u0645\u0633\u062a\u0634\u0639\u0631 \u0627\u0647\u062a\u0632\u0627\u0632",
    "integration.intelligence": "\u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a / \u062e\u0628\u064a\u0631 / \u062a\u0637\u0628\u064a\u0642",
    "integration.sap": "\u0625\u0634\u0639\u0627\u0631 IW31",
    "integration.maintainx": "\u0623\u0645\u0631 \u0639\u0645\u0644 \u0645\u064f\u0639\u064a\u0651\u0646 \u0641\u064a MaintainX",
    "integration.grafana": "\u062a\u0646\u0628\u064a\u0647 \u0644\u0648\u062d\u0629 Grafana",
    "integration.note": "\u062d\u062f\u062b \u0648\u0627\u062d\u062f\u060c \u062b\u0644\u0627\u062b\u0629 \u0645\u0633\u062a\u0647\u0644\u0643\u064a\u0646. \u0644\u0627 \u062a\u0643\u0627\u0645\u0644 \u0645\u062e\u0635\u0635 \u0644\u0643\u0644 \u0646\u0638\u0627\u0645 \u0647\u062f\u0641. \u0633\u0648\u0627\u0621 \u0643\u0627\u0646 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a\u064b\u0627 \u0623\u0648 \u0628\u0634\u0631\u064a\u064b\u0627 \u2014 \u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u062d\u062f\u062b \u0648\u0627\u062d\u062f.",
    "incident.title": "\u062f\u0648\u0631\u0629 \u062d\u064a\u0627\u0629 \u0627\u0644\u062d\u0627\u062f\u062b",
    "incident.subtitle": "\u062d\u0627\u062f\u062b \u0643\u0627\u0645\u0644 \u0645\u0646 \u0627\u0644\u0627\u0643\u062a\u0634\u0627\u0641 \u0625\u0644\u0649 \u0627\u0644\u062d\u0644. \u0623\u0631\u0628\u0639\u0629 \u0623\u062d\u062f\u0627\u062b IAES \u062a\u0631\u0648\u064a \u0627\u0644\u0642\u0635\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u2014 \u062f\u0648\u0646 \u062a\u062f\u062e\u0644 \u0628\u0634\u0631\u064a \u0644\u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u062a\u0646\u0628\u064a\u0647.",
    "incident.onset_desc": "\u064a\u0646\u062e\u0641\u0636 \u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u0642\u062f\u0631\u0629 \u0625\u0644\u0649 0.91. \u064a\u0643\u062a\u0634\u0641 \u0645\u062d\u0631\u0643 \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0643. \u064a\u064f\u0646\u0634\u0623 correlation_id \u062c\u062f\u064a\u062f. \u064a\u064f\u0646\u0634\u0623 \u0623\u0648\u0644 \u062a\u0646\u0628\u064a\u0647.",
    "incident.escalation_desc": "\u064a\u0646\u062e\u0641\u0636 \u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u0642\u062f\u0631\u0629 \u0623\u0643\u062b\u0631 \u0625\u0644\u0649 0.84. \u062a\u064f\u0631\u0641\u0639 \u0627\u0644\u062e\u0637\u0648\u0631\u0629 \u0645\u0646 severity: medium \u0625\u0644\u0649 high. \u0646\u0641\u0633 correlation_id. \u0644\u0627 \u062a\u0646\u0628\u064a\u0647 \u0645\u0643\u0631\u0631 \u2014 \u064a\u064f\u062d\u062f\u0651\u062b \u0627\u0644\u062a\u0646\u0628\u064a\u0647 \u0627\u0644\u062d\u0627\u0644\u064a.",
    "incident.wo_desc": "\u064a\u064f\u0646\u0634\u0626 \u0627\u0644\u0645\u0633\u062a\u0647\u0644\u0643 \u0623\u0645\u0631 \u0639\u0645\u0644 \u0641\u064a MaintainX. \u0645\u0631\u062a\u0628\u0637 \u0628\u0646\u0641\u0633 correlation_id. \u064a\u064f\u0631\u0633\u0644 \u0641\u0646\u064a \u0644\u0641\u062d\u0635 \u0628\u0646\u0643 \u0627\u0644\u0645\u0643\u062b\u0641\u0627\u062a.",
    "incident.recovery_desc": "\u064a\u062a\u0639\u0627\u0641\u0649 \u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u0642\u062f\u0631\u0629 \u0625\u0644\u0649 0.97 \u0644\u0645\u062f\u0629 5 \u0642\u0631\u0627\u0621\u0627\u062a \u0645\u062a\u062a\u0627\u0644\u064a\u0629. \u064a\u064f\u0635\u062f\u0631 \u062d\u062f\u062b \u062a\u0639\u0627\u0641\u064d \u0628\u0640 severity: info \u0648 condition_trend: improving. \u064a\u064f\u063a\u0644\u0642 \u0627\u0644\u062a\u0646\u0628\u064a\u0647 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627.",
    "incident.correlation": "correlation_id: 3b2f9d8c-1c33-4a8a \u2014 \u062a\u0634\u062a\u0631\u0643 \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u0623\u0631\u0628\u0639\u0629 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0645\u0639\u0631\u0651\u0641. \u062d\u0627\u062f\u062b \u0648\u0627\u062d\u062f\u060c \u0633\u0644\u0633\u0644\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u062a\u062a\u0628\u0639 \u0643\u0627\u0645\u0644.",
