    "integration.title": "\u0938\u0947\u0902\u0938\u0930 \u0938\u0947 \u0915\u093e\u0930\u094d\u0930\u0935\u093e\u0908 \u0924\u0915",
    "integration.subtitle": "\u090f\u0915 \u0938\u0947\u0902\u0938\u0930 \u092c\u0947\u092f\u0930\u093f\u0902\u0917 \u0915\u0947 \u0918\u093f\u0938\u093e\u0935 \u0915\u093e \u092a\u0924\u093e \u0932\u0917\u093e\u0924\u093e \u0939\u0948\u0964 \u090f\u0915 AI \u092e\u0949\u0921\u0932 \u0926\u094b\u0937 \u0915\u094b \u0935\u0930\u094d\u0917\u0940\u0915\u0943\u0924 \u0915\u0930\u0924\u093e \u0939\u0948 \u2014 \u092f\u093e \u0915\u094b\u0908 \u0924\u0915\u0928\u0940\u0936\u093f\u092f\u0928 \u092e\u094b\u092c\u093e\u0907\u0932 \u0910\u092a \u0938\u0947 \u0928\u093f\u0926\u093e\u0928 \u0926\u0930\u094d\u091c \u0915\u0930\u0924\u093e \u0939\u0948\u0964 \u0926\u094b\u0928\u094b\u0902 \u0938\u094d\u0925\u093f\u0924\u093f\u092f\u094b\u0902 \u092e\u0947\u0902, IAES \u090f\u0915 \u0907\u0935\u0947\u0902\u091f \u0915\u094b \u0924\u0940\u0928 \u0938\u093f\u0938\u094d\u091f\u092e\u094b\u0902 \u092e\u0947\u0902 \u090f\u0915 \u0938\u093e\u0925 \u092d\u0947\u091c\u0924\u093e \u0939\u0948\u0964",
    "integration.sensor": "\u0915\u0902\u092a\u0928 \u0938\u0947\u0902\u0938\u0930",
    "integration.intelligence": "AI / \u0935\u093f\u0936\u0947\u0937\u091c\u094d\u091e / \u0910\u092a",
    "integration.sap": "IW31 \u0938\u0942\u091a\u0928\u093e",
    "integration.maintainx": "MaintainX \u092e\u0947\u0902 \u0915\u093e\u0930\u094d\u092f \u0906\u0926\u0947\u0936 \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924",
    "integration.grafana": "Grafana \u0905\u0932\u0930\u094d\u091f \u092a\u0948\u0928\u0932 \u0938\u0915\u094d\u0930\u093f\u092f",
    "integration.note": "\u090f\u0915 \u0907\u0935\u0947\u0902\u091f, \u0924\u0940\u0928 \u0909\u092a\u092d\u094b\u0915\u094d\u0924\u093e\u0964 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0932\u0915\u094d\u0937\u094d\u092f \u0938\u093f\u0938\u094d\u091f\u092e \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u0915\u0938\u094d\u091f\u092e \u0907\u0902\u091f\u0940\u0917\u094d\u0930\u0947\u0936\u0928 \u0928\u0939\u0940\u0902\u0964 \u091a\u093e\u0939\u0947 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e \u0915\u0943\u0924\u094d\u0930\u093f\u092e \u0939\u094b \u092f\u093e \u092e\u093e\u0928\u0935\u0940\u092f \u2014 \u0907\u0935\u0947\u0902\u091f \u092b\u0949\u0930\u094d\u092e\u0947\u091f \u090f\u0915 \u0939\u0940 \u0939\u0948\u0964",
    "incident.title": "\u0918\u091f\u0928\u093e \u091c\u0940\u0935\u0928\u091a\u0915\u094d\u0930",
    "incident.subtitle": "\u092a\u0924\u093e \u0932\u0917\u093e\u0928\u0947 \u0938\u0947 \u0938\u092e\u093e\u0927\u093e\u0928 \u0924\u0915 \u090f\u0915 \u092a\u0942\u0930\u094d\u0923 \u0918\u091f\u0928\u093e\u0964 \u091a\u093e\u0930 IAES \u0907\u0935\u0947\u0902\u091f \u092a\u0942\u0930\u0940 \u0915\u0939\u093e\u0928\u0940 \u092c\u0924\u093e\u0924\u0947 \u0939\u0948\u0902 \u2014 \u0905\u0932\u0930\u094d\u091f \u092c\u0902\u0926 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u093f\u0938\u0940 \u092e\u093e\u0928\u0935\u0940\u092f \u0939\u0938\u094d\u0924\u0915\u094d\u0937\u0947\u092a \u0915\u0940 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e \u0928\u0939\u0940\u0902\u0964",
    "incident.onset_desc": "\u092a\u093e\u0935\u0930 \u092b\u0948\u0915\u094d\u091f\u0930 0.91 \u0924\u0915 \u0917\u093f\u0930\u0924\u093e \u0939\u0948\u0964 \u0928\u093f\u092f\u092e \u0907\u0902\u091c\u0928 \u0909\u0932\u094d\u0932\u0902\u0918\u0928 \u0915\u093e \u092a\u0924\u093e \u0932\u0917\u093e\u0924\u093e \u0939\u0948\u0964 \u0928\u092f\u093e correlation_id \u091c\u0928\u0930\u0947\u091f \u0939\u094b\u0924\u093e \u0939\u0948\u0964 \u092a\u0939\u0932\u093e \u0905\u0932\u0930\u094d\u091f \u092c\u0928\u0924\u093e \u0939\u0948\u0964",
    "incident.escalation_desc": "\u092a\u093e\u0935\u0930 \u092b\u0948\u0915\u094d\u091f\u0930 \u0914\u0930 \u0917\u093f\u0930\u0915\u0930 0.84 \u0939\u094b\u0924\u093e \u0939\u0948\u0964 severity: medium \u0938\u0947 high \u092e\u0947\u0902 \u092c\u0922\u093c\u093e\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964 \u0935\u0939\u0940 correlation_id\u0964 \u0915\u094b\u0908 \u0921\u0941\u092a\u094d\u0932\u093f\u0915\u0947\u091f \u0905\u0932\u0930\u094d\u091f \u0928\u0939\u0940\u0902 \u2014 \u092e\u094c\u091c\u0942\u0926\u093e \u0905\u0932\u0930\u094d\u091f \u0905\u092a\u0921\u0947\u091f \u0939\u094b\u0924\u093e \u0939\u0948\u0964",
    "incident.wo_desc": "\u0909\u092a\u092d\u094b\u0915\u094d\u0924\u093e MaintainX \u092e\u0947\u0902 \u0915\u093e\u0930\u094d\u092f \u0906\u0926\u0947\u0936 \u092c\u0928\u093e\u0924\u093e \u0939\u0948\u0964 \u0909\u0938\u0940 correlation_id \u0938\u0947 \u091c\u0941\u0921\u093c\u093e\u0964 \u0915\u0948\u092a\u0947\u0938\u093f\u091f\u0930 \u092c\u0948\u0902\u0915 \u0915\u0940 \u091c\u093e\u0901\u091a \u0915\u0947 \u0932\u093f\u090f \u0924\u0915\u0928\u0940\u0936\u093f\u092f\u0928 \u092d\u0947\u091c\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964",
    "incident.recovery_desc": "\u092a\u093e\u0935\u0930 \u092b\u0948\u0915\u094d\u091f\u0930 5 \u0932\u0917\u093e\u0924\u093e\u0930 \u0930\u0940\u0921\u093f\u0902\u0917 \u0915\u0947 \u0932\u093f\u090f 0.97 \u092a\u0930 \u0935\u093e\u092a\u0938 \u0906\u0924\u093e \u0939\u0948\u0964 severity: info \u0914\u0930 condition_trend: improving \u0915\u0947 \u0938\u093e\u0925 \u0930\u093f\u0915\u0935\u0930\u0940 \u0907\u0935\u0947\u0902\u091f \u091c\u093e\u0930\u0940 \u0939\u094b\u0924\u093e \u0939\u0948\u0964 \u0905\u0932\u0930\u094d\u091f \u0938\u094d\u0935\u0924\u0903 \u0939\u0932 \u0939\u094b\u0924\u093e \u0939\u0948\u0964",
    "incident.correlation": "correlation_id: 3b2f9d8c-1c33-4a8a \u2014 \u091a\u093e\u0930\u094b\u0902 \u0907\u0935\u0947\u0902\u091f \u090f\u0915 \u0939\u0940 ID \u0938\u093e\u091d\u093e \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964 \u090f\u0915 \u0918\u091f\u0928\u093e, \u090f\u0915 \u0925\u094d\u0930\u0947\u0921, \u092a\u0942\u0930\u094d\u0923 \u091f\u094d\u0930\u0947\u0938\u0947\u092c\u093f\u0932\u093f\u091f\u0940\u0964",
